function ToolChip({ tool }: { tool: Tool }) {
  const icon = ICONS[tool.slug];
  if (!icon) return null;

  return (
    <div
      title={tool.name}
      role="img"
      aria-label={tool.name}
      className={[
        "flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl bg-white/95 dark:bg-neutral-900/90 border border-slate-200 dark:border-white/10 shadow-md dark:shadow-lg backdrop-blur-md transition-all duration-300 hover:scale-110 hover:border-cyan-500/50 hover:shadow-cyan-500/20 text-slate-900 dark:text-white",
        tool.featured ? "ring-2 ring-cyan-500/70 dark:ring-cyan-400/70 border-cyan-500/40" : "",
      ].join(" ")}
    >
      <svg
        viewBox="0 0 24 24"
        className="h-8 w-8 transition-transform group-hover:scale-105"
        fill={icon.hex === "#FFFFFF" ? "currentColor" : icon.hex}
        aria-hidden="true"
      >
        <path d={icon.path} />
      </svg>
    </div>
  );
}

function MarqueeRow({ row, index }: { row: Row; index: number }) {
  const looped = [...row.tools, ...row.tools];
  const durations = ["26s", "32s", "28s"];

  const set = (copy: number) => (
    <div
      className="flex shrink-0 gap-6 pr-6"
      aria-hidden={copy === 1 ? true : undefined}
    >
      {looped.map((tool, i) => (
        <ToolChip key={`${copy}-${i}-${tool.name}`} tool={tool} />
      ))}
    </div>
  );

  return (
    <div className="marquee-row group relative overflow-hidden py-2.5">
      <div
        className={
          row.direction === "left" ? "animate-marquee-left" : "animate-marquee-right"
        }
        style={{ animationDuration: durations[index % durations.length] }}
      >
        {set(0)}
        {set(1)}
      </div>
    </div>
  );
}

